style.css:
@-moz-document domain("discord.com") {
/* ===== CHANGE THIS TO YOUR WALLPAPER ===== */
:root {
    --haimiya-wallpaper: url("https://YOUR_IMAGE_LINK_HERE.jpg");
}

/* Background */
body,
#app-mount,
.appMount__51fd7,
.bg__960e4,
.app__160d8 {
    background: var(--haimiya-wallpaper) center center / cover no-repeat fixed !important;
}

/* Main Panels */
.chat_f75fb0,
.container__133bf,
.content_f75fb0,
.membersWrap_cbd271,
.sidebar_c48ade,
.panels_c48ade,
.guilds_c48ade,
.container__2637a,
.container__9293f {
    background: rgba(20, 20, 30, 0.45) !important;
    backdrop-filter: blur(14px) !important;
    -webkit-backdrop-filter: blur(14px) !important;
}

/* Messages */
.message_d5deea:hover {
    background: rgba(255,255,255,.05) !important;
}

/* Text box */
.form_f75fb0,
.channelTextArea_f75fb0 {
    background: rgba(15,15,20,.55) !important;
    backdrop-filter: blur(12px);
}

/* Popouts & Menus */
.menu_d90b3d,
.layer_da8173,
.container_ac201b,
.popout_a6e77f,
.root_f9a4c9 {
    background: rgba(25,25,35,.75) !important;
    backdrop-filter: blur(20px);
}

/* Remove solid backgrounds */
[class*="theme-dark"] {
    --background-primary: transparent !important;
    --background-secondary: transparent !important;
    --background-secondary-alt: transparent !important;
    --background-tertiary: rgba(0,0,0,.15) !important;
    --channeltextarea-background: rgba(0,0,0,.35) !important;
    --background-floating: rgba(20,20,30,.80) !important;
}

/* Rounded corners */
.chat_f75fb0,
.sidebar_c48ade,
.membersWrap_cbd271 {
    border-radius: 16px;
}
}
